def count_wonderful_substrings(word):
    frequencies = {0: 1}
    mask = 0
    answer = 0
    for char in word:
        mask ^= 1 << (ord(char) - ord("a"))
        answer += frequencies.get(mask, 0)
        for bit in range(10):
            answer += frequencies.get(mask ^ (1 << bit), 0)
        frequencies[mask] = frequencies.get(mask, 0) + 1
    return answer

